    KnowledgeEntry(
        id='sim_swap_fraud',
        topic='sim_swap',
        related_module='m3',
        keywords={'en': ['sim swap', 'sim replacement', 'lost signal', 'no signal', 'sim card scam', 'ethio telecom sim', 'otp theft'], 'om': ['sim swap', 'jijjiirraa sim', 'siimiin bade', 'sararri cite', 'gowwoomsaa sim', 'saamicha otp'], 'am': ['የሲም ካርድ ቅያሬ', 'ሲም ስዋፕ', 'ኔትወርክ ጠፋ', 'የሲም ማጭበርበር', 'የኦቲፒ ስርቆት', 'ኢትዮ ቴሌኮም ሲም']},
        title={'en': 'SIM Swap Fraud & Mobile Account Defense', 'om': 'Gowwoomsaa Jijjiirraa SIM (SIM Swap) Ittisuu', 'am': 'የሲም ካርድ ቅያሬ (SIM Swap) ማጭበርበር መከላከያ'},
        summary={'en': 'SIM swapping occurs when an attacker fraudulently convinces a mobile telecom operator to reassign your phone number to a new SIM card they control, intercepting your SMS verification codes and bank OTPs.', 'om': 'SIM swap jechuun yakkamuun dhaabbata telekoomii gowwoomsuun lakkoofsa bilbila keessan gara kaardii SIM isaanii kan haaraatti akka jijjiiramu gochuun koodii OTP saamuudha.', 'am': 'ሲም ስዋፕ አጥቂዎች ቴሌኮምን በማታለል የእርስዎን ስልክ ቁጥር ወደ እጃቸው ሲም ካርድ በማዛወር የባንክና የማህበራዊ ሚዲያ የኦቲፒ (OTP) ሚስጥር ቁጥሮችን የሚሰርቁበት አደገኛ የማጭበርበር ዘዴ ነው።'},
        details={'en': "Warning signs: Your mobile phone abruptly loses all cellular reception ('Emergency calls only' or 'No service') while others around you have normal coverage, followed by unauthorized password reset alerts on your email.", 'om': "Mallattoolee: Bilbilli keessan battalatti tajaajila sararaa dhabuu ('No Service' ykn 'Emergency calls only'), yeroo kanatti immoo herregni keessan akka jijjiiramaa jiru ergaan imeelii irratti dhufuu.", 'am': "ጠቋሚ ምልክቶች፡ በዙሪያዎ ያሉ ሰዎች ኔትወርክ እያላቸው የእርስዎ ስልክ ድንገት አገልግሎት ማቋረጡ ('No Service' ወይም 'Emergency calls only' ማለቱ)፣ በመቀጠልም የይለፍ ቃል መቀየሩን የሚገልጹ የኢሜይል መልእክቶች መድረሳቸው።"},
        examples={'en': 'A fraudster uses forged ID papers to port your number at a telecom kiosk. Within minutes, they reset your mobile banking password and drain funds via SMS confirmation.', 'om': 'Yakkamaan waraqaa eenyummaa sobaa qabatee gara telekoomii deemuun lakkoofsa kee jijjiirrata, achiis herrega baankii kee saama.', 'am': 'አጭበርባሪው የተጭበረበረ መታወቂያ በመጠቀም ስልክ ቁጥርዎን ወደ ሌላ ሲም ያስቀይራል፤ በደቂቃዎች ውስጥ የባንክ ሂሳብዎን በኤስኤምኤስ ኮድ ከፍቶ ገንዘብ ያወጣል።'},
        next_steps={'en': '1. If your phone unexpectedly loses service, call Ethio Telecom immediately (994) from another phone. 2. Contact your bank to temporarily freeze mobile transactions. 3. Switch important accounts from SMS 2FA to app authenticators.', 'om': '1. Bilbilli kee tajaajila yoo dhabe battalatti bilbila biraatiin Ethio Telecom (994) bilbili. 2. Baankii keetti bilbilii herregni kee akka cufamu godhi. 3. SMS 2FA dhiisiitii appilikeeshinii fayyadami.', 'am': '1. ስልክዎ ያለ ምክንያት ኔትወርክ ካጣ አሁኑኑ በሌላ ስልክ ወደ ኢትዮ ቴሌኮም (994) ይደውሉ። 2. የባንክ ሂሳብዎ ለጊዜው እንዲታገድ ባንክዎን ያሳውቁ። 3. የማረጋገጫ ኮዶችን በኤስኤምኤስ ፋንታ በመተግበሪያ (Authenticator) እንዲደርሱ ያድርጉ።'},
        limitations={'en': 'Offline detection cannot check your current live SIM registration or carrier network provisioning status.', 'om': "Gorsi toora alaa kun teessoo SIM keessanii yeroo ammaa qorachuu hin danda'u.", 'am': 'ይህ ከመስመር ውጭ መመሪያ የሲም ካርድዎን የቀጥታ ሁኔታ ከቴሌኮም ጋር ማረጋገጥ አይችልም።'},
        suggested_followups={'en': ['What is 2FA?', 'How to draft an incident report in M3?', 'What should I do next?'], 'om': ['2FA jechuun maali?', 'M3 keessatti gabaasa akkamitti qopheessu?', 'Tarkaanfii itti aanu maalan godha?'], 'am': ['2FA ምንድን ነው?', 'በM3 ሪፖርት እንዴት ላዘጋጅ?', 'ቀጥሎ ምን ማድረግ አለብኝ?']},
    ),
