def normalize_query(text: str) -> str:
    """
    Normalizes spelling, typos, technical jargon, Ethiopian Latin apostrophes,
    and informal technical question variations.
    """
    if not text:
        return ""
    q = text.lower().strip()
    # Normalize punctuation and Ethiopian Latin apostrophes
    q = re.sub(r"['’`]", "'", q)
    q = q.replace('"', ' ')
    q = re.sub(r"[\?!,;:()\-]+", " ", q)

    # Common spelling & tech term normalization
    replacements = [
        (r"\bfishing\b", "phishing"),
        (r"\bfishin\b", "phishing"),
        (r"\bpasword\b", "password"),
        (r"\bpassward\b", "password"),
        (r"\bpaswrd\b", "password"),
        (r"\bpass\s+code\b", "password"),
        (r"\bcyber\s+security\b", "cybersecurity"),
        (r"\bcyberscurity\b", "cybersecurity"),
        (r"\bcybr\b", "cyber"),
        (r"\btelebir\b", "telebirr"),
        (r"\btlebirr\b", "telebirr"),
        (r"\bmal\s+ware\b", "malware"),
        (r"\bransome\b", "ransomware"),
        (r"\bransome\s+ware\b", "ransomware"),
        (r"\bspy\s+ware\b", "spyware"),
        (r"\bauthen\b", "authentication"),
        (r"\bauthentification\b", "authentication"),
        (r"\bauthoriz\b", "authorization"),
        (r"\bboundry\b", "boundary"),
        (r"\bboundries\b", "boundaries"),
        (r"\betical\b", "ethical"),
        (r"\bwi\s*fi\b", "wifi"),
        (r"\bwlan\b", "wifi"),
    ]
    for pattern, replacement in replacements:
        q = re.sub(pattern, replacement, q)

    return re.sub(r"\s+", " ", q).strip()


def find_matching_knowledge(
    query: str,
    language: str = "en",
) -> Optional[KnowledgeEntry]:
    """
    Searches the verified knowledge base for the most relevant entry.
    Applies normalization, exact phrase bonuses, multi-word matching, and keyword scoring.
    """
    norm_q = normalize_query(query)
    if not norm_q:
        return None

    best_entry: Optional[KnowledgeEntry] = None
    best_score = 0

    for entry in KNOWLEDGE_ENTRIES:
        score = 0
        lang_keys = entry.keywords.get(language, [])
        en_keys = entry.keywords.get("en", [])
        all_keys = set(lang_keys + en_keys)

        for kw in all_keys:
            kw_norm = normalize_query(kw)
            if not kw_norm:
                continue

            # Exact phrase match gives high boost
            if kw_norm in norm_q:
                word_count = len(kw_norm.split())
                score += word_count * 5 + (3 if kw in lang_keys else 1)
            elif any(w in norm_q.split() for w in kw_norm.split() if len(w) > 3):
                # Partial token overlap
                score += 1

        # Check direct topic match
        if entry.topic in norm_q or entry.id in norm_q:
            score += 8

        # Check related module match
        if entry.related_module and entry.related_module in norm_q.split():
            score += 4

        if score > best_score:
            best_score = score
            best_entry = entry

    # Minimum score threshold
    if best_score >= 3:
        return best_entry

    return None


def get_entry_by_id(entry_id: str) -> Optional[KnowledgeEntry]:
    """Retrieves a specific knowledge entry by id."""
    for entry in KNOWLEDGE_ENTRIES:
        if entry.id == entry_id:
            return entry
    return None
